contracts/AdminController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title AdminController
 * @dev Enhanced role-based access control for game contracts
 * Provides multiple admin levels and better security controls
 */
contract AdminController {
    // ================================
    // STORAGE
    // ================================

    // Role definitions
    enum Role {
        NONE,
        OPERATOR, // Can perform basic operations
        MANAGER, // Can manage game settings
        ADMIN, // Can manage contracts and admins
        OWNER // Full control
    }

    // Role assignments
    mapping(address => Role) public userRoles;

    // Contract ownership
    address public owner;
    bool public paused = false;

    // Emergency controls
    bool public emergencyMode = false;
    address public emergencyAdmin;

    // ================================
    // EVENTS
    // ================================
    event RoleUpdated(address indexed user, Role oldRole, Role newRole);
    event OwnerUpdated(address indexed oldOwner, address indexed newOwner);
    event ContractPaused(bool paused);
    event EmergencyModeUpdated(bool emergencyMode);
    event EmergencyAdminUpdated(
        address indexed oldAdmin,
        address indexed newAdmin
    );

    // ================================
    // MODIFIERS
    // ================================

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    modifier onlyAdmin() {
        require(
            userRoles[msg.sender] >= Role.ADMIN,
            "Only admin or higher can call this function"
        );
        _;
    }

    modifier onlyManager() {
        require(
            userRoles[msg.sender] >= Role.MANAGER,
            "Only manager or higher can call this function"
        );
        _;
    }

    modifier onlyOperator() {
        require(
            userRoles[msg.sender] >= Role.OPERATOR,
            "Only operator or higher can call this function"
        );
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    modifier whenNotEmergency() {
        require(!emergencyMode, "Contract is in emergency mode");
        _;
    }

    // ================================
    // CONSTRUCTOR
    // ================================

    constructor() {
        owner = msg.sender;
        userRoles[msg.sender] = Role.OWNER;
        emergencyAdmin = msg.sender;
    }

    // ================================
    // VIEW FUNCTIONS
    // ================================

    /**
     * @dev Gets the role of a user
     * @param _user The user address
     * @return The user's role
     */
    function getUserRole(address _user) external view returns (Role) {
        return userRoles[_user];
    }

    /**
     * @dev Checks if a user has a specific role or higher
     * @param _user The user address
     * @param _role The required role
     * @return True if user has the role or higher
     */
    function hasRole(address _user, Role _role) external view returns (bool) {
        return userRoles[_user] >= _role;
    }

    /**
     * @dev Gets contract status information
     * @return _owner Owner address
     * @return _paused Whether contract is paused
     * @return _emergencyMode Whether emergency mode is active
     * @return _emergencyAdmin Emergency admin address
     */
    function getContractInfo()
        external
        view
        returns (
            address _owner,
            bool _paused,
            bool _emergencyMode,
            address _emergencyAdmin
        )
    {
        return (owner, paused, emergencyMode, emergencyAdmin);
    }

    // ================================
    // ADMIN FUNCTIONS
    // ================================

    /**
     * @dev Sets a user's role (only admin or higher)
     * @param _user The user address
     * @param _role The new role
     */
    function setUserRole(
        address _user,
        Role _role
    ) external onlyAdmin whenNotPaused {
        require(_user != address(0), "Invalid address");
        Role oldRole = userRoles[_user];
        userRoles[_user] = _role;
        emit RoleUpdated(_user, oldRole, _role);
    }

    /**
     * @dev Updates the owner (only owner)
     * @param _newOwner The new owner address
     */
    function setOwner(address _newOwner) external onlyOwner {
        require(_newOwner != address(0), "Invalid address");
        address oldOwner = owner;
        owner = _newOwner;
        userRoles[_newOwner] = Role.OWNER;
        emit OwnerUpdated(oldOwner, _newOwner);
    }

    /**
     * @dev Pauses or unpauses the contract (only admin or higher)
     * @param _paused True to pause, false to unpause
     */
    function setPaused(bool _paused) external onlyAdmin {
        paused = _paused;
        emit ContractPaused(_paused);
    }

    /**
     * @dev Sets emergency mode (only emergency admin)
     * @param _emergencyMode True to enable emergency mode
     */
    function setEmergencyMode(bool _emergencyMode) external {
        require(
            msg.sender == emergencyAdmin || userRoles[msg.sender] >= Role.ADMIN,
            "Only emergency admin or admin can call this function"
        );
        emergencyMode = _emergencyMode;
        emit EmergencyModeUpdated(_emergencyMode);
    }

    /**
     * @dev Updates the emergency admin (only owner)
     * @param _newEmergencyAdmin The new emergency admin address
     */
    function setEmergencyAdmin(address _newEmergencyAdmin) external onlyOwner {
        require(_newEmergencyAdmin != address(0), "Invalid address");
        address oldAdmin = emergencyAdmin;
        emergencyAdmin = _newEmergencyAdmin;
        emit EmergencyAdminUpdated(oldAdmin, _newEmergencyAdmin);
    }

    /**
     * @dev Emergency function to revoke all roles except owner (only emergency admin)
     * @param _users Array of user addresses to revoke
     */
    function emergencyRevokeRoles(address[] calldata _users) external {
        require(
            msg.sender == emergencyAdmin || userRoles[msg.sender] >= Role.ADMIN,
            "Only emergency admin or admin can call this function"
        );
        for (uint256 i = 0; i < _users.length; i++) {
            if (_users[i] != owner) {
                Role oldRole = userRoles[_users[i]];
                userRoles[_users[i]] = Role.NONE;
                emit RoleUpdated(_users[i], oldRole, Role.NONE);
            }
        }
    }

    // ================================
    // UTILITY FUNCTIONS
    // ================================

    /**
     * @dev Checks if a user can perform an operation based on role requirements
     * @param _user The user address
     * @param _requiredRole The required role level
     * @return True if user can perform the operation
     */
    function canPerformOperation(
        address _user,
        Role _requiredRole
    ) external view returns (bool) {
        if (emergencyMode) {
            return _user == emergencyAdmin || _user == owner;
        }
        return userRoles[_user] >= _requiredRole;
    }

    /**
     * @dev Gets all users with a specific role or higher
     * @param _role The minimum role to include
     * @return Array of user addresses
     */
    function getUsersWithRole(
        Role _role
    ) external view returns (address[] memory) {
        // This is a simplified implementation
        // In a real implementation, you might want to maintain a list of users
        return new address[](0);
    }
}

contracts/GameRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IRICEManager.sol";
import "./interfaces/IScoreBoard.sol";
import "./interfaces/IPowerUpManager.sol";

/**
 * @title GameRegistry
 * @dev Central registry for managing game contract addresses and admin controls
 * Provides a single point of truth for contract addresses and admin functions
 */
contract GameRegistry {
    // ================================
    // STORAGE
    // ================================

    // Contract addresses
    address public riceManager;
    address public scoreBoard;
    address public powerUpManager;

    // Admin controls
    address public gameOwner;
    address public gameServer;
    bool public paused = false;

    // Role-based access control
    mapping(address => bool) public authorizedContracts;
    mapping(address => bool) public authorizedAdmins;

    // ================================
    // EVENTS
    // ================================
    event ContractAddressUpdated(string contractName, address oldAddress, address newAddress);
    event GameOwnerUpdated(address indexed oldOwner, address indexed newOwner);
    event GameServerUpdated(address indexed oldServer, address indexed newServer);
    event ContractPaused(bool paused);
    event AuthorizedContractUpdated(address indexed contractAddress, bool authorized);
    event AuthorizedAdminUpdated(address indexed admin, bool authorized);

    // ================================
    // MODIFIERS
    // ================================

    modifier onlyGameOwner() {
        require(msg.sender == gameOwner, "Only game owner can call this function");
        _;
    }

    modifier onlyAuthorizedAdmin() {
        require(
            msg.sender == gameOwner || authorizedAdmins[msg.sender],
            "Only authorized admin can call this function"
        );
        _;
    }

    modifier onlyAuthorizedContract() {
        require(
            authorizedContracts[msg.sender],
            "Only authorized contract can call this function"
        );
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Registry is paused");
        _;
    }

    // ================================
    // CONSTRUCTOR
    // ================================

    constructor() {
        gameOwner = msg.sender;
        authorizedAdmins[msg.sender] = true;
    }

    // ================================
    // VIEW FUNCTIONS
    // ================================

    /**
     * @dev Gets all contract addresses
     * @return _riceManager RICEManager address
     * @return _scoreBoard ScoreBoard address
     * @return _powerUpManager PowerUpManager address
     */
    function getContractAddresses() external view returns (
        address _riceManager,
        address _scoreBoard,
        address _powerUpManager
    ) {
        return (riceManager, scoreBoard, powerUpManager);
    }

    /**
     * @dev Gets admin information
     * @return _gameOwner Game owner address
     * @return _gameServer Game server address
     * @return _paused Whether registry is paused
     */
    function getAdminInfo() external view returns (
        address _gameOwner,
        address _gameServer,
        bool _paused
    ) {
        return (gameOwner, gameServer, _paused);
    }

    /**
     * @dev Checks if an address is an authorized contract
     * @param _contract The contract address to check
     * @return True if authorized
     */
    function isAuthorizedContract(address _contract) external view returns (bool) {
        return authorizedContracts[_contract];
    }

    /**
     * @dev Checks if an address is an authorized admin
     * @param _admin The admin address to check
     * @return True if authorized
     */
    function isAuthorizedAdmin(address _admin) external view returns (bool) {
        return _admin == gameOwner || authorizedAdmins[_admin];
    }

    // ================================
    // ADMIN FUNCTIONS
    // ================================

    /**
     * @dev Sets the RICEManager contract address
     * @param _riceManager The new RICEManager address
     */
    function setRICEManager(address _riceManager) external onlyAuthorizedAdmin whenNotPaused {
        require(_riceManager != address(0), "Invalid address");
        address oldAddress = riceManager;
        riceManager = _riceManager;
        authorizedContracts[_riceManager] = true;
        emit ContractAddressUpdated("RICEManager", oldAddress, _riceManager);
    }

    /**
     * @dev Sets the ScoreBoard contract address
     * @param _scoreBoard The new ScoreBoard address
     */
    function setScoreBoard(address _scoreBoard) external onlyAuthorizedAdmin whenNotPaused {
        require(_scoreBoard != address(0), "Invalid address");
        address oldAddress = scoreBoard;
        scoreBoard = _scoreBoard;
        authorizedContracts[_scoreBoard] = true;
        emit ContractAddressUpdated("ScoreBoard", oldAddress, _scoreBoard);
    }

    /**
     * @dev Sets the PowerUpManager contract address
     * @param _powerUpManager The new PowerUpManager address
     */
    function setPowerUpManager(address _powerUpManager) external onlyAuthorizedAdmin whenNotPaused {
        require(_powerUpManager != address(0), "Invalid address");
        address oldAddress = powerUpManager;
        powerUpManager = _powerUpManager;
        authorizedContracts[_powerUpManager] = true;
        emit ContractAddressUpdated("PowerUpManager", oldAddress, _powerUpManager);
    }

    /**
     * @dev Sets the game server address
     * @param _gameServer The new game server address
     */
    function setGameServer(address _gameServer) external onlyAuthorizedAdmin whenNotPaused {
        require(_gameServer != address(0), "Invalid address");
        address oldServer = gameServer;
        gameServer = _gameServer;
        emit GameServerUpdated(oldServer, _gameServer);
    }

    /**
     * @dev Updates the game owner
     * @param _newOwner The new game owner address
     */
    function setGameOwner(address _newOwner) external onlyGameOwner {
        require(_newOwner != address(0), "Invalid address");
        address oldOwner = gameOwner;
        gameOwner = _newOwner;
        authorizedAdmins[_newOwner] = true;
        emit GameOwnerUpdated(oldOwner, _newOwner);
    }

    /**
     * @dev Pauses or unpauses the registry
     * @param _paused True to pause, false to unpause
     */
    function setPaused(bool _paused) external onlyAuthorizedAdmin {
        paused = _paused;
        emit ContractPaused(_paused);
    }

    /**
     * @dev Authorizes or deauthorizes a contract
     * @param _contract The contract address
     * @param _authorized True to authorize, false to deauthorize
     */
    function setAuthorizedContract(address _contract, bool _authorized) external onlyAuthorizedAdmin {
        authorizedContracts[_contract] = _authorized;
        emit AuthorizedContractUpdated(_contract, _authorized);
    }

    /**
     * @dev Authorizes or deauthorizes an admin
     * @param _admin The admin address
     * @param _authorized True to authorize, false to deauthorize
     */
    function setAuthorizedAdmin(address _admin, bool _authorized) external onlyGameOwner {
        authorizedAdmins[_admin] = _authorized;
        emit AuthorizedAdminUpdated(_admin, _authorized);
    }

    // ================================
    // CONTRACT INTERFACE FUNCTIONS
    // ================================

    /**
     * @dev Gets RICE balance for a player via RICEManager
     * @param _player The player's address
     * @return The player's RICE balance
     */
    function getRICEBalance(address _player) external view returns (uint256) {
        require(riceManager != address(0), "RICEManager not set");
        return IRICEManager(riceManager).getBalance(_player);
    }

    /**
     * @dev Gets player's best score via ScoreBoard
     * @param _player The player's address
     * @return The player's best score
     */
    function getPlayerBestScore(address _player) external view returns (uint256) {
        require(scoreBoard != address(0), "ScoreBoard not set");
        return IScoreBoard(scoreBoard).getPlayerBestScore(_player);
    }

    /**
     * @dev Gets player's power-up levels via PowerUpManager
     * @param _player The player's address
     * @return Array of power-up levels
     */
    function getPowerUpLevels(address _player) external view returns (uint256[] memory) {
        require(powerUpManager != address(0), "PowerUpManager not set");
        return IPowerUpManager(powerUpManager).getPowerUpLevels(_player);
    }

    /**
     * @dev Gets leaderboard via ScoreBoard
     * @param _offset Starting index for pagination
     * @param _limit Number of entries to return
     * @return Array of leaderboard entries
     */
    function getLeaderboard(uint256 _offset, uint256 _limit) external view returns (IScoreBoard.LeaderboardEntry[] memory) {
        require(scoreBoard != address(0), "ScoreBoard not set");
        return IScoreBoard(scoreBoard).getLeaderboard(_offset, _limit);
    }
}

contracts/interfaces/IPowerUpManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IPowerUpManager
 * @dev Interface for PowerUpManager contract
 * Provides functions for managing power-up upgrades and configurations
 */
interface IPowerUpManager {
    // ================================
    // EVENTS
    // ================================
    event PowerUpUpgraded(
        address indexed player,
        uint256 indexed powerUpId,
        uint256 oldLevel,
        uint256 newLevel,
        uint256 cost,
        bytes32 upgradeHash
    );
    event PowerUpConfigured(
        uint256 indexed powerUpId,
        uint256 baseCost,
        uint256 maxLevel
    );
    event GameOwnerUpdated(address indexed oldOwner, address indexed newOwner);
    event ContractPaused(bool paused);
    event GameServerUpdated(
        address indexed oldServer,
        address indexed newServer
    );
    event RICEManagerUpdated(
        address indexed oldManager,
        address indexed newManager
    );

    // ================================
    // VIEW FUNCTIONS
    // ================================

    /**
     * @dev Returns levels of the first 10 power-ups for a player
     * @param player The player's address
     * @return Array of power-up levels (1-indexed)
     */
    function getPowerUpLevels(
        address player
    ) external view returns (uint256[] memory);

    /**
     * @dev Returns base cost and maxLevel of a power-up
     * @param powerUpId The power-up ID
     * @return baseCost The base cost of the power-up
     * @return maxLevel The maximum level of the power-up
     */
    function getPowerUpConfig(
        uint256 powerUpId
    ) external view returns (uint256 baseCost, uint256 maxLevel);

    /**
     * @dev Gets the cost to upgrade to a specific level
     * @param powerUpId The power-up ID
     * @param level The target level
     * @return cost The cost to upgrade to that level
     */
    function getPowerUpLevelCost(
        uint256 powerUpId,
        uint256 level
    ) external view returns (uint256 cost);

    /**
     * @dev Gets the cost to upgrade the next level for a player
     * @param player The player's address
     * @param powerUpId The power-up ID
     * @return cost The cost to upgrade to the next level
     */
    function getPowerUpUpgradeCost(
        address player,
        uint256 powerUpId
    ) external view returns (uint256 cost);

    /**
     * @dev Gets contract information
     * @return _gameOwner The game owner address
     * @return _paused Whether the contract is paused
     * @return _minTimeBetweenUpgrades Minimum time between upgrades
     * @return _securityKeySet Whether security key is set
     */
    function getContractInfo()
        external
        view
        returns (
            address _gameOwner,
            bool _paused,
            uint256 _minTimeBetweenUpgrades,
            bool _securityKeySet
        );

    // ================================
    // STATE-CHANGING FUNCTIONS
    // ================================

    /**
     * @dev Sets base cost and max level of a power-up (on-chain)
     * @param powerUpId The power-up ID
     * @param baseCost The base cost
     * @param maxLevel The maximum level
     */
    function setPowerUp(
        uint256 powerUpId,
        uint256 baseCost,
        uint256 maxLevel
    ) external;

    /**
     * @dev Upgrades power-up with signature verification
     * @param player The player's address
     * @param powerUpId The power-up ID
     * @param upgradeHash Unique upgrade hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function upgradePowerUp(
        address player,
        uint256 powerUpId,
        bytes32 upgradeHash,
        bytes memory signature
    ) external;

    /**
     * @dev Emergency function to set power-up without signature (for testing)
     * @param powerUpId The power-up ID
     * @param baseCost The base cost
     * @param maxLevel The maximum level
     */
    function setPowerUpEmergency(
        uint256 powerUpId,
        uint256 baseCost,
        uint256 maxLevel
    ) external;

    /**
     * @dev Emergency function to upgrade power-up without signature (for testing)
     * @param player The player's address
     * @param powerUpId The power-up ID
     */
    function upgradePowerUpEmergency(
        address player,
        uint256 powerUpId
    ) external;

    // ================================
    // ADMIN FUNCTIONS
    // ================================

    /**
     * @dev Sets the security key for signing operations
     * @param _securityKey The security key to set
     */
    function setSecurityKey(bytes32 _securityKey) external;

    /**
     * @dev Updates the game owner
     * @param _newOwner The new game owner address
     */
    function setGameOwner(address _newOwner) external;

    /**
     * @dev Pauses or unpauses the contract
     * @param _paused True to pause, false to unpause
     */
    function setPaused(bool _paused) external;

    /**
     * @dev Updates the game server address
     * @param _gameServer The new game server address
     */
    function setGameServer(address _gameServer) external;

    /**
     * @dev Updates the RICEManager address
     * @param _riceManager The new RICEManager address
     */
    function setRiceManager(address _riceManager) external;
}

contracts/interfaces/IRICEManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IRICEManager
 * @dev Interface for RICEManager contract
 * Provides functions for managing RICE token balances and operations
 */
interface IRICEManager {
    // ================================
    // EVENTS
    // ================================
    event RICEAdded(
        address indexed player,
        uint256 amount,
        bytes32 operationHash
    );
    event RICESpent(
        address indexed player,
        uint256 amount,
        bytes32 operationHash
    );
    event DailyRevealRICEAdded(
        address indexed player,
        uint256 amount,
        bytes32 operationHash
    );
    event GameOwnerUpdated(address indexed oldOwner, address indexed newOwner);
    event ContractPaused(bool paused);
    event SecurityKeyUpdated(bytes32 newKey);
    event ScoreBoardAddressUpdated(address indexed newAddress);
    event PowerUpManagerAddressUpdated(address indexed newAddress);

    // ================================
    // VIEW FUNCTIONS
    // ================================

    /**
     * @dev Gets the RICE balance for a player
     * @param player The player's address
     * @return The player's RICE balance
     */
    function getBalance(address player) external view returns (uint256);

    /**
     * @dev Checks if player can claim daily reveal
     * @param player The player's address
     * @return True if player can claim daily reveal
     */
    function canClaimDailyReveal(address player) external view returns (bool);

    /**
     * @dev Gets the time until next daily reveal can be claimed
     * @param player The player's address
     * @return Time in seconds until next claim
     */
    function getTimeUntilNextDailyReveal(
        address player
    ) external view returns (uint256);

    /**
     * @dev Gets contract information
     * @return _gameOwner The game owner address
     * @return _paused Whether the contract is paused
     * @return _minTimeBetweenOperations Minimum time between operations
     * @return _securityKeySet Whether security key is set
     * @return _dailyRevealCooldown Daily reveal cooldown period
     */
    function getContractInfo()
        external
        view
        returns (
            address _gameOwner,
            bool _paused,
            uint256 _minTimeBetweenOperations,
            bool _securityKeySet,
            uint256 _dailyRevealCooldown
        );

    // ================================
    // STATE-CHANGING FUNCTIONS
    // ================================

    /**
     * @dev Adds RICE to a player's balance with signature verification
     * @param player The player's address
     * @param amount The amount of RICE to add
     * @param operationHash Unique operation hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function addRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external;

    /**
     * @dev Adds RICE from daily reveal with signature verification
     * @param player The player's address
     * @param amount The amount of RICE to add
     * @param operationHash Unique operation hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function addDailyRevealRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external;

    /**
     * @dev Spends RICE from a player's balance with signature verification
     * @param player The player's address
     * @param amount The amount of RICE to spend
     * @param operationHash Unique operation hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function spendRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external;

    /**
     * @dev Emergency function to add RICE without signature (for authorized contracts)
     * @param player The player's address
     * @param amount The amount of RICE to add
     * @param operationHash Unique operation hash
     */
    function addRICEEmergency(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external;

    /**
     * @dev Emergency function to spend RICE without signature (for authorized contracts)
     * @param player The player's address
     * @param amount The amount of RICE to spend
     * @param operationHash Unique operation hash
     */
    function spendRICEEmergency(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external;

    /**
     * @dev Emergency function to spend RICE for PowerUpManager without signature
     * @param player The player's address
     * @param amount The amount of RICE to spend
     * @param operationHash Unique operation hash
     */
    function spendRICEEmergencyForPowerUp(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external;

    // ================================
    // ADMIN FUNCTIONS
    // ================================

    /**
     * @dev Sets the game owner
     * @param _newOwner The new game owner address
     */
    function setGameOwner(address _newOwner) external;

    /**
     * @dev Pauses or unpauses the contract
     * @param _paused True to pause, false to unpause
     */
    function setPaused(bool _paused) external;

    /**
     * @dev Sets the security key for signing operations
     * @param _securityKey The new security key
     */
    function setSecurityKey(bytes32 _securityKey) external;

    /**
     * @dev Sets the ScoreBoard contract address
     * @param _scoreBoardAddress The ScoreBoard contract address
     */
    function setScoreBoardAddress(address _scoreBoardAddress) external;

    /**
     * @dev Sets the PowerUpManager contract address
     * @param _powerUpManagerAddress The PowerUpManager contract address
     */
    function setPowerUpManagerAddress(address _powerUpManagerAddress) external;
}

contracts/interfaces/IScoreBoard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title IScoreBoard
 * @dev Interface for ScoreBoard contract
 * Provides functions for managing game scores and leaderboards
 */
interface IScoreBoard {
    // ================================
    // STRUCTS
    // ================================
    struct Score {
        uint256 score;
        uint256 timestamp;
        string playerName;
        bytes32 gameHash; // Hash to verify score authenticity
    }

    struct LeaderboardEntry {
        uint256 score;
        string playerName;
        address playerAddress;
    }

    // ================================
    // EVENTS
    // ================================
    event ScoreRecorded(
        address indexed player,
        uint256 score,
        uint256 timestamp,
        bytes32 gameHash
    );
    event ScoreRecordedWithRICE(
        address indexed player,
        uint256 score,
        uint256 riceReward,
        uint256 timestamp,
        bytes32 gameHash
    );
    event BestScoreUpdated(address indexed player, uint256 newBestScore);
    event GameOwnerUpdated(address indexed oldOwner, address indexed newOwner);
    event ContractPaused(bool paused);
    event SecurityKeyUpdated(bytes32 newKey);
    event RICEManagerAddressUpdated(address indexed newAddress);

    // ================================
    // VIEW FUNCTIONS
    // ================================

    /**
     * @dev Gets all scores for a player
     * @param _player The player's address
     * @return Array of Score structs
     */
    function getPlayerScores(
        address _player
    ) external view returns (Score[] memory);

    /**
     * @dev Gets the best score for a player
     * @param _player The player's address
     * @return The player's best score
     */
    function getPlayerBestScore(
        address _player
    ) external view returns (uint256);

    /**
     * @dev Gets the number of scores for a player
     * @param _player The player's address
     * @return Number of scores
     */
    function getScoreCount(address _player) external view returns (uint256);

    /**
     * @dev Gets the global leaderboard with pagination
     * @param _offset Starting index for pagination
     * @param _limit Number of entries to return
     * @return Array of LeaderboardEntry structs
     */
    function getLeaderboard(
        uint256 _offset,
        uint256 _limit
    ) external view returns (LeaderboardEntry[] memory);

    /**
     * @dev Gets the total number of players in the leaderboard
     * @return Total number of players
     */
    function getTotalScores() external view returns (uint256);

    /**
     * @dev Gets contract information
     * @return _gameOwner The game owner address
     * @return _paused Whether the contract is paused
     * @return _minTimeBetweenScores Minimum time between scores
     * @return _securityKeySet Whether security key is set
     */
    function getContractInfo()
        external
        view
        returns (
            address _gameOwner,
            bool _paused,
            uint256 _minTimeBetweenScores,
            bool _securityKeySet
        );

    // ================================
    // STATE-CHANGING FUNCTIONS
    // ================================

    /**
     * @dev Records a score with signature verification
     * @param _score The score to record
     * @param _playerName The player's name
     * @param _gameHash Unique game hash to verify authenticity
     * @param _signature Signature created with the security key
     */
    function recordScore(
        uint256 _score,
        string memory _playerName,
        bytes32 _gameHash,
        bytes memory _signature
    ) external;

    /**
     * @dev Records a score and adds RICE rewards in a single transaction
     * @param _score The score to record
     * @param _playerName The player's name
     * @param _riceReward The amount of RICE to add as reward
     * @param _gameHash Unique game hash to verify authenticity
     * @param _signature Signature created with the security key
     */
    function recordScoreWithRICE(
        uint256 _score,
        string memory _playerName,
        uint256 _riceReward,
        bytes32 _gameHash,
        bytes memory _signature
    ) external;

    /**
     * @dev Emergency function to record a score without signature (for testing)
     * @param _score The score to record
     * @param _playerName The player's name
     * @param _playerAddress The player's address
     * @param _gameHash Unique game hash
     */
    function recordScoreEmergency(
        uint256 _score,
        string memory _playerName,
        address _playerAddress,
        bytes32 _gameHash
    ) external;

    // ================================
    // ADMIN FUNCTIONS
    // ================================

    /**
     * @dev Sets the game owner
     * @param _newOwner The new game owner address
     */
    function setGameOwner(address _newOwner) external;

    /**
     * @dev Pauses or unpauses the contract
     * @param _paused True to pause, false to unpause
     */
    function setPaused(bool _paused) external;

    /**
     * @dev Sets the security key for signing scores
     * @param _securityKey The new security key
     */
    function setSecurityKey(bytes32 _securityKey) external;

    /**
     * @dev Sets the RICEManager contract address
     * @param _riceManagerAddress The address of the RICEManager contract
     */
    function setRICEManagerAddress(address _riceManagerAddress) external;
}

contracts/PowerUpManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IRICEManager.sol";
import "./interfaces/IPowerUpManager.sol";

/**
 * @title PowerUpManager
 * @dev Manages power-up upgrades and configurations with signature verification
 * Implements IPowerUpManager interface for modularity
 */
contract PowerUpManager is IPowerUpManager {
    // ================================
    // STORAGE
    // ================================
    mapping(address => mapping(uint256 => uint256)) public levels; // player => powerUpId => level
    mapping(uint256 => uint256) public powerUpBaseCosts; // powerUpId => base cost
    mapping(uint256 => uint256) public powerUpMaxLevels; // powerUpId => max level
    mapping(uint256 => mapping(uint256 => uint256)) public powerUpLevelCosts; // powerUpId => level => cost

    // Security and ownership
    address public gameOwner; // Address autorisée à gérer le contrat
    bool public paused = false;

    // Security key for signing operations (set by game owner)
    bytes32 public securityKey;
    bool public securityKeySet = false;

    // Contract addresses
    address public riceManager;
    address public gameServer;

    // Anti-spam protection
    mapping(address => uint256) public lastUpgradeTimestamp;
    uint256 public constant MIN_TIME_BETWEEN_UPGRADES = 30 seconds;

    // Prevent upgrade reuse
    mapping(bytes32 => bool) public usedUpgradeHashes;

    // Events are now defined in the interface

    modifier onlyGameOwner() {
        require(
            msg.sender == gameOwner,
            "Only game owner can call this function"
        );
        _;
    }

    modifier onlyGameServer() {
        require(msg.sender == gameServer, "Not authorized");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    constructor(address _riceManager, address _gameServer) {
        gameOwner = msg.sender;
        riceManager = _riceManager;
        gameServer = _gameServer;
    }

    /**
     * @dev Sets the security key for signing operations
     * @param _securityKey The security key to set
     */
    function setSecurityKey(bytes32 _securityKey) external onlyGameOwner {
        securityKey = _securityKey;
        securityKeySet = true;
    }

    /**
     * @dev Updates the game owner
     * @param _newOwner The new game owner address
     */
    function setGameOwner(address _newOwner) external onlyGameOwner {
        require(_newOwner != address(0), "Invalid address");
        address oldOwner = gameOwner;
        gameOwner = _newOwner;
        emit GameOwnerUpdated(oldOwner, _newOwner);
    }

    /**
     * @dev Pauses or unpauses the contract
     * @param _paused True to pause, false to unpause
     */
    function setPaused(bool _paused) external onlyGameOwner {
        paused = _paused;
        emit ContractPaused(_paused);
    }

    /**
     * @dev Updates the game server address
     * @param _gameServer The new game server address
     */
    function setGameServer(address _gameServer) external onlyGameOwner {
        require(_gameServer != address(0), "Invalid address");
        address oldServer = gameServer;
        gameServer = _gameServer;
        emit GameServerUpdated(oldServer, _gameServer);
    }

    /**
     * @dev Updates the RICEManager address
     * @param _riceManager The new RICEManager address
     */
    function setRiceManager(address _riceManager) external onlyGameOwner {
        require(_riceManager != address(0), "Invalid address");
        address oldManager = riceManager;
        riceManager = _riceManager;
        emit RICEManagerUpdated(oldManager, _riceManager);
    }

    /// @notice Set base cost and max level of a power-up (on-chain)
    function setPowerUp(
        uint256 powerUpId,
        uint256 baseCost,
        uint256 maxLevel
    ) external onlyGameServer whenNotPaused {
        require(baseCost > 0, "Base cost must be greater than 0");
        require(maxLevel > 0, "Max level must be greater than 0");

        powerUpBaseCosts[powerUpId] = baseCost;
        powerUpMaxLevels[powerUpId] = maxLevel;

        // Initialize level costs with a progression
        for (uint256 level = 1; level <= maxLevel; level++) {
            powerUpLevelCosts[powerUpId][level] = baseCost * level * level; // Quadratic progression
        }

        emit PowerUpConfigured(powerUpId, baseCost, maxLevel);
    }

    /// @notice Upgrade power-up with signature verification
    function upgradePowerUp(
        address player,
        uint256 powerUpId,
        bytes32 upgradeHash,
        bytes memory signature
    ) external whenNotPaused {
        require(!usedUpgradeHashes[upgradeHash], "Upgrade hash already used");
        require(
            block.timestamp >=
                lastUpgradeTimestamp[player] + MIN_TIME_BETWEEN_UPGRADES,
            "Too soon since last upgrade"
        );
        require(securityKeySet, "Security key not set");

        uint256 currentLevel = levels[player][powerUpId];
        uint256 maxLevel = powerUpMaxLevels[powerUpId];
        require(maxLevel > 0, "Power-up not initialized");
        require(currentLevel < maxLevel, "Already max level");

        uint256 cost = powerUpLevelCosts[powerUpId][currentLevel + 1];

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                "UPGRADE_POWERUP",
                player,
                powerUpId,
                cost,
                upgradeHash
            )
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedUpgradeHashes[upgradeHash] = true;
        lastUpgradeTimestamp[player] = block.timestamp;

        // Spend RICE and upgrade (now using RICE units, not wei)
        IRICEManager(riceManager).spendRICEEmergencyForPowerUp(
            player,
            cost, // Cost in RICE units, not wei
            bytes32(0)
        );
        levels[player][powerUpId]++;

        emit PowerUpUpgraded(
            player,
            powerUpId,
            currentLevel,
            levels[player][powerUpId],
            cost,
            upgradeHash
        );
    }

    /// @notice Emergency function to set power-up without signature (for testing)
    function setPowerUpEmergency(
        uint256 powerUpId,
        uint256 baseCost,
        uint256 maxLevel
    ) external onlyGameOwner whenNotPaused {
        require(baseCost > 0, "Base cost must be greater than 0");
        require(maxLevel > 0, "Max level must be greater than 0");

        powerUpBaseCosts[powerUpId] = baseCost;
        powerUpMaxLevels[powerUpId] = maxLevel;

        // Initialize level costs with a progression
        for (uint256 level = 1; level <= maxLevel; level++) {
            powerUpLevelCosts[powerUpId][level] = baseCost * level * level; // Quadratic progression
        }

        emit PowerUpConfigured(powerUpId, baseCost, maxLevel);
    }

    /// @notice Emergency function to upgrade power-up without signature (for testing)
    function upgradePowerUpEmergency(
        address player,
        uint256 powerUpId
    ) external whenNotPaused {
        uint256 currentLevel = levels[player][powerUpId];
        uint256 maxLevel = powerUpMaxLevels[powerUpId];
        require(maxLevel > 0, "Power-up not initialized");
        require(currentLevel < maxLevel, "Already max level");

        uint256 cost = powerUpLevelCosts[powerUpId][currentLevel + 1];

        IRICEManager(riceManager).spendRICEEmergencyForPowerUp(
            player,
            cost, // Convert RICE to wei
            bytes32(0)
        );
        levels[player][powerUpId]++;

        emit PowerUpUpgraded(
            player,
            powerUpId,
            currentLevel,
            levels[player][powerUpId],
            cost,
            bytes32(0)
        );
    }

    /// @notice Return levels of the 10 first power-ups for a player
    function getPowerUpLevels(
        address player
    ) external view returns (uint256[] memory) {
        uint256 count = 10;
        uint256[] memory result = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            // Return level + 1 so players start at level 1 instead of 0
            result[i] = levels[player][i] + 1;
        }
        return result;
    }

    /// @notice Return base cost and maxLevel of a power-up
    function getPowerUpConfig(
        uint256 powerUpId
    ) external view returns (uint256 baseCost, uint256 maxLevel) {
        return (powerUpBaseCosts[powerUpId], powerUpMaxLevels[powerUpId]);
    }

    /// @notice Get the cost to upgrade to a specific level
    function getPowerUpLevelCost(
        uint256 powerUpId,
        uint256 level
    ) external view returns (uint256 cost) {
        return powerUpLevelCosts[powerUpId][level];
    }

    /// @notice Get the cost to upgrade the next level for a player
    function getPowerUpUpgradeCost(
        address player,
        uint256 powerUpId
    ) external view returns (uint256 cost) {
        uint256 currentLevel = levels[player][powerUpId];
        // Calculate cost for the next level (currentLevel + 1)
        return powerUpLevelCosts[powerUpId][currentLevel + 1];
    }

    /**
     * @dev Recovers the signer from a signature
     */
    function recoverSigner(
        bytes32 _ethSignedMessageHash,
        bytes memory _signature
    ) internal pure returns (address) {
        require(_signature.length == 65, "Invalid signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(_signature, 32))
            s := mload(add(_signature, 64))
            v := byte(0, mload(add(_signature, 96)))
        }

        if (v < 27) {
            v += 27;
        }

        require(v == 27 || v == 28, "Invalid signature 'v' value");

        return ecrecover(_ethSignedMessageHash, v, r, s);
    }

    /// @notice Get contract information
    function getContractInfo()
        external
        view
        returns (
            address _gameOwner,
            bool _paused,
            uint256 _minTimeBetweenUpgrades,
            bool _securityKeySet
        )
    {
        return (gameOwner, paused, MIN_TIME_BETWEEN_UPGRADES, securityKeySet);
    }
}

contracts/RICEManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IRICEManager.sol";

/**
 * @title RICEManager
 * @dev Manages RICE token balances and operations with signature verification
 * Implements IRICEManager interface for modularity
 */
contract RICEManager is IRICEManager {
    mapping(address => uint256) public balances;

    // Security and ownership
    address public gameOwner; // Address autorisée à gérer le contrat
    bool public paused = false;

    // Security key for signing operations (set by game owner)
    bytes32 public securityKey;
    bool public securityKeySet = false;

    // ScoreBoard contract address (set by game owner)
    address public scoreBoardAddress;

    // Anti-spam protection
    mapping(address => uint256) public lastOperationTimestamp;
    uint256 public constant MIN_TIME_BETWEEN_OPERATIONS = 30 seconds;

    // Prevent operation reuse
    mapping(bytes32 => bool) public usedOperationHashes;

    // Contract addresses
    address public powerUpManagerAddress;

    // Daily reveal tracking
    mapping(address => uint256) public lastDailyRevealTimestamp;
    uint256 public constant DAILY_REVEAL_COOLDOWN = 24 hours;

    // Events are now defined in the interface

    modifier onlyGameOwner() {
        require(
            msg.sender == gameOwner,
            "Only game owner can call this function"
        );
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    modifier onlyScoreBoard() {
        require(
            msg.sender == scoreBoardAddress,
            "Only ScoreBoard can call this function"
        );
        _;
    }

    modifier onlyPowerUpManager() {
        require(
            msg.sender == powerUpManagerAddress,
            "Only PowerUpManager can call this function"
        );
        _;
    }

    constructor() {
        gameOwner = msg.sender;
    }

    /**
     * @dev Adds RICE to a player's balance with signature verification
     * @param player The player's address
     * @param amount The amount of RICE to add (in RICE units, not wei)
     * @param operationHash Unique operation hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function addRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );
        require(
            block.timestamp >=
                lastOperationTimestamp[player] + MIN_TIME_BETWEEN_OPERATIONS,
            "Too soon since last operation"
        );
        require(securityKeySet, "Security key not set");

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked("ADD_RICE", player, amount, operationHash)
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedOperationHashes[operationHash] = true;
        lastOperationTimestamp[player] = block.timestamp;

        balances[player] += amount;
        emit RICEAdded(player, amount, operationHash);
    }

    /**
     * @dev Adds RICE from daily reveal with signature verification
     * @param player The player's address
     * @param amount The amount of RICE to add (in RICE units, not wei)
     * @param operationHash Unique operation hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function addDailyRevealRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );
        require(
            block.timestamp >=
                lastDailyRevealTimestamp[player] + DAILY_REVEAL_COOLDOWN,
            "Daily reveal already claimed today"
        );
        require(securityKeySet, "Security key not set");

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked("DAILY_REVEAL_RICE", player, amount, operationHash)
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedOperationHashes[operationHash] = true;
        lastDailyRevealTimestamp[player] = block.timestamp;

        balances[player] += amount;
        emit DailyRevealRICEAdded(player, amount, operationHash);
    }

    /**
     * @dev Spends RICE from a player's balance with signature verification
     * @param player The player's address
     * @param amount The amount of RICE to spend (in RICE units, not wei)
     * @param operationHash Unique operation hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function spendRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(balances[player] >= amount, "Not enough RICE");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );
        require(
            block.timestamp >=
                lastOperationTimestamp[player] + MIN_TIME_BETWEEN_OPERATIONS,
            "Too soon since last operation"
        );
        require(securityKeySet, "Security key not set");

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked("SPEND_RICE", player, amount, operationHash)
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedOperationHashes[operationHash] = true;
        lastOperationTimestamp[player] = block.timestamp;

        balances[player] -= amount;
        emit RICESpent(player, amount, operationHash);
    }

    /**
     * @dev Emergency function to add RICE without signature (for testing)
     * Only accessible by the ScoreBoard contract
     * @param player The player's address
     * @param amount The amount of RICE to add (in RICE units, not wei)
     * @param operationHash Unique operation hash
     */
    function addRICEEmergency(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external onlyScoreBoard whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );

        usedOperationHashes[operationHash] = true;
        balances[player] += amount;
        emit RICEAdded(player, amount, operationHash);
    }

    /**
     * @dev Emergency function to spend RICE without signature (for testing)
     * Only accessible by the game owner
     * @param player The player's address
     * @param amount The amount of RICE to spend (in RICE units, not wei)
     * @param operationHash Unique operation hash
     */
    function spendRICEEmergency(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external onlyGameOwner whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(balances[player] >= amount, "Not enough RICE");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );

        usedOperationHashes[operationHash] = true;
        balances[player] -= amount;
        emit RICESpent(player, amount, operationHash);
    }

    /**
     * @dev Emergency function to spend RICE for PowerUpManager without signature
     * Only accessible by the PowerUpManager contract
     * @param player The player's address
     * @param amount The amount of RICE to spend (in RICE units, not wei)
     * @param operationHash Unique operation hash
     */
    function spendRICEEmergencyForPowerUp(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external onlyPowerUpManager whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(balances[player] >= amount, "Not enough RICE");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );

        usedOperationHashes[operationHash] = true;
        balances[player] -= amount;
        emit RICESpent(player, amount, operationHash);
    }

    /**
     * @dev Recovers the signer from a signature
     */
    function recoverSigner(
        bytes32 _ethSignedMessageHash,
        bytes memory _signature
    ) internal pure returns (address) {
        require(_signature.length == 65, "Invalid signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(_signature, 32))
            s := mload(add(_signature, 64))
            v := byte(0, mload(add(_signature, 96)))
        }

        if (v < 27) {
            v += 27;
        }

        require(v == 27 || v == 28, "Invalid signature 'v' value");

        return ecrecover(_ethSignedMessageHash, v, r, s);
    }

    /**
     * @dev Gets the RICE balance for a player (in RICE units, not wei)
     * @param player The player's address
     * @return The player's RICE balance
     */
    function getBalance(address player) external view returns (uint256) {
        return balances[player];
    }

    /**
     * @dev Checks if player can claim daily reveal
     * @param player The player's address
     * @return True if player can claim daily reveal
     */
    function canClaimDailyReveal(address player) external view returns (bool) {
        return
            block.timestamp >=
            lastDailyRevealTimestamp[player] + DAILY_REVEAL_COOLDOWN;
    }

    /**
     * @dev Gets the time until next daily reveal can be claimed
     * @param player The player's address
     * @return Time in seconds until next claim
     */
    function getTimeUntilNextDailyReveal(
        address player
    ) external view returns (uint256) {
        uint256 nextClaimTime = lastDailyRevealTimestamp[player] +
            DAILY_REVEAL_COOLDOWN;
        if (block.timestamp >= nextClaimTime) {
            return 0;
        }
        return nextClaimTime - block.timestamp;
    }

    /**
     * @dev Administrative functions
     */
    function setGameOwner(address _newOwner) public onlyGameOwner {
        require(_newOwner != address(0), "Invalid address");
        address oldOwner = gameOwner;
        gameOwner = _newOwner;
        emit GameOwnerUpdated(oldOwner, _newOwner);
    }

    function setPaused(bool _paused) public onlyGameOwner {
        paused = _paused;
        emit ContractPaused(_paused);
    }

    /**
     * @dev Sets the security key for signing operations
     * @param _securityKey The new security key
     */
    function setSecurityKey(bytes32 _securityKey) public onlyGameOwner {
        securityKey = _securityKey;
        securityKeySet = true;
        emit SecurityKeyUpdated(_securityKey);
    }

    /**
     * @dev Sets the ScoreBoard contract address
     * @param _scoreBoardAddress The ScoreBoard contract address
     */
    function setScoreBoardAddress(
        address _scoreBoardAddress
    ) public onlyGameOwner {
        require(_scoreBoardAddress != address(0), "Invalid address");
        scoreBoardAddress = _scoreBoardAddress;
        emit ScoreBoardAddressUpdated(_scoreBoardAddress);
    }

    /**
     * @dev Sets the PowerUpManager contract address
     * @param _powerUpManagerAddress The PowerUpManager contract address
     */
    function setPowerUpManagerAddress(
        address _powerUpManagerAddress
    ) public onlyGameOwner {
        require(_powerUpManagerAddress != address(0), "Invalid address");
        powerUpManagerAddress = _powerUpManagerAddress;
        emit PowerUpManagerAddressUpdated(_powerUpManagerAddress);
    }

    function getContractInfo()
        public
        view
        returns (
            address _gameOwner,
            bool _paused,
            uint256 _minTimeBetweenOperations,
            bool _securityKeySet,
            uint256 _dailyRevealCooldown
        )
    {
        return (
            gameOwner,
            paused,
            MIN_TIME_BETWEEN_OPERATIONS,
            securityKeySet,
            DAILY_REVEAL_COOLDOWN
        );
    }
}

contracts/ScoreBoard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./interfaces/IRICEManager.sol";
import "./interfaces/IScoreBoard.sol";

/**
 * @title ScoreBoard
 * @dev Manages game scores and leaderboards with signature verification
 * Implements IScoreBoard interface for modularity
 */
contract ScoreBoard is IScoreBoard {
    mapping(address => Score[]) public playerScores;
    mapping(address => uint256) public playerBestScore;
    mapping(address => uint256) public lastScoreTimestamp; // Anti-spam protection
    mapping(bytes32 => bool) public usedGameHashes; // Prevent score reuse

    // Global leaderboard tracking
    address[] public allPlayers;
    mapping(address => bool) public playerExists;
    mapping(address => string) public playerNames; // Store player names

    uint256 public constant MIN_TIME_BETWEEN_SCORES = 5 seconds; // Minimum time between scores

    address public gameOwner; // Address authorized to manage the contract
    bool public paused = false;

    // RICEManager contract address
    address public riceManagerAddress;

    // Security key for signing scores (set by game owner)
    bytes32 public securityKey;
    bool public securityKeySet = false;

    modifier onlyGameOwner() {
        require(
            msg.sender == gameOwner,
            "Only game owner can call this function"
        );
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    constructor() {
        gameOwner = msg.sender;
    }

    /**
     * @dev Sets the RICEManager contract address
     * @param _riceManagerAddress The address of the RICEManager contract
     */
    function setRICEManagerAddress(
        address _riceManagerAddress
    ) public onlyGameOwner {
        require(_riceManagerAddress != address(0), "Invalid address");
        riceManagerAddress = _riceManagerAddress;
        emit RICEManagerAddressUpdated(_riceManagerAddress);
    }

    /**
     * @dev Records a score - ANY PLAYER CAN CALL THIS FUNCTION WITH VALID SIGNATURE
     * @param _score The score to record
     * @param _playerName The player's name
     * @param _gameHash Unique game hash to verify authenticity
     * @param _signature Signature created with the security key
     */
    function recordScore(
        uint256 _score,
        string memory _playerName,
        bytes32 _gameHash,
        bytes memory _signature
    ) public whenNotPaused {
        require(_score > 0, "Score must be greater than 0");
        require(!usedGameHashes[_gameHash], "Game hash already used");
        require(
            block.timestamp >=
                lastScoreTimestamp[msg.sender] + MIN_TIME_BETWEEN_SCORES,
            "Too soon since last score"
        );
        require(securityKeySet, "Security key not set");

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked(_score, _playerName, msg.sender, _gameHash)
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, _signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedGameHashes[_gameHash] = true;

        Score memory newScore = Score({
            score: _score,
            timestamp: block.timestamp,
            playerName: _playerName,
            gameHash: _gameHash
        });

        playerScores[msg.sender].push(newScore);
        lastScoreTimestamp[msg.sender] = block.timestamp;

        // Add player to global tracking if not already present
        if (!playerExists[msg.sender]) {
            allPlayers.push(msg.sender);
            playerExists[msg.sender] = true;
            playerNames[msg.sender] = _playerName;
        }

        // Update best score if this is higher
        if (_score > playerBestScore[msg.sender]) {
            playerBestScore[msg.sender] = _score;
            emit BestScoreUpdated(msg.sender, _score);
        }

        emit ScoreRecorded(msg.sender, _score, block.timestamp, _gameHash);
    }

    /**
     * @dev Records a score and adds RICE rewards in a single transaction
     * @param _score The score to record
     * @param _playerName The player's name
     * @param _riceReward The amount of RICE to add as reward
     * @param _gameHash Unique game hash to verify authenticity
     * @param _signature Signature created with the security key
     */
    function recordScoreWithRICE(
        uint256 _score,
        string memory _playerName,
        uint256 _riceReward,
        bytes32 _gameHash,
        bytes memory _signature
    ) public whenNotPaused {
        require(_score > 0, "Score must be greater than 0");
        require(_riceReward > 0, "RICE reward must be greater than 0");
        require(!usedGameHashes[_gameHash], "Game hash already used");
        require(
            block.timestamp >=
                lastScoreTimestamp[msg.sender] + MIN_TIME_BETWEEN_SCORES,
            "Too soon since last score"
        );
        require(securityKeySet, "Security key not set");
        require(riceManagerAddress != address(0), "RICEManager not configured");

        // Verify the signature - using the same format as the API
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                _score,
                _playerName,
                _riceReward,
                msg.sender,
                _gameHash
            )
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, _signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedGameHashes[_gameHash] = true;

        Score memory newScore = Score({
            score: _score,
            timestamp: block.timestamp,
            playerName: _playerName,
            gameHash: _gameHash
        });

        playerScores[msg.sender].push(newScore);
        lastScoreTimestamp[msg.sender] = block.timestamp;

        // Add player to global tracking if not already present
        if (!playerExists[msg.sender]) {
            allPlayers.push(msg.sender);
            playerExists[msg.sender] = true;
            playerNames[msg.sender] = _playerName;
        }

        // Update best score if this is higher
        if (_score > playerBestScore[msg.sender]) {
            playerBestScore[msg.sender] = _score;
            emit BestScoreUpdated(msg.sender, _score);
        }

        // Add RICE rewards via RICEManager (using emergency function since we already verified the signature)
        IRICEManager(riceManagerAddress).addRICEEmergency(
            msg.sender,
            _riceReward, // RICE reward in RICE units, not wei
            _gameHash
        );

        emit ScoreRecordedWithRICE(
            msg.sender,
            _score,
            _riceReward,
            block.timestamp,
            _gameHash
        );
    }

    /**
     * @dev Emergency function to record a score without signature (for testing)
     * Only accessible by the game owner
     */
    function recordScoreEmergency(
        uint256 _score,
        string memory _playerName,
        address _playerAddress,
        bytes32 _gameHash
    ) public onlyGameOwner whenNotPaused {
        require(_score > 0, "Score must be greater than 0");
        require(!usedGameHashes[_gameHash], "Game hash already used");

        usedGameHashes[_gameHash] = true;

        Score memory newScore = Score({
            score: _score,
            timestamp: block.timestamp,
            playerName: _playerName,
            gameHash: _gameHash
        });

        playerScores[_playerAddress].push(newScore);

        // Add player to global tracking if not already present
        if (!playerExists[_playerAddress]) {
            allPlayers.push(_playerAddress);
            playerExists[_playerAddress] = true;
            playerNames[_playerAddress] = _playerName;
        }

        if (_score > playerBestScore[_playerAddress]) {
            playerBestScore[_playerAddress] = _score;
            emit BestScoreUpdated(_playerAddress, _score);
        }

        emit ScoreRecorded(_playerAddress, _score, block.timestamp, _gameHash);
    }

    /**
     * @dev Recovers the signer from a signature
     */
    function recoverSigner(
        bytes32 _ethSignedMessageHash,
        bytes memory _signature
    ) internal pure returns (address) {
        require(_signature.length == 65, "Invalid signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(_signature, 32))
            s := mload(add(_signature, 64))
            v := byte(0, mload(add(_signature, 96)))
        }

        if (v < 27) {
            v += 27;
        }

        require(v == 27 || v == 28, "Invalid signature 'v' value");

        return ecrecover(_ethSignedMessageHash, v, r, s);
    }

    function getPlayerScores(
        address _player
    ) public view returns (Score[] memory) {
        return playerScores[_player];
    }

    function getPlayerBestScore(address _player) public view returns (uint256) {
        return playerBestScore[_player];
    }

    function getScoreCount(address _player) public view returns (uint256) {
        return playerScores[_player].length;
    }

    /**
     * @dev Gets the global leaderboard with pagination
     * @param _offset Starting index for pagination
     * @param _limit Number of entries to return
     * @return Array of LeaderboardEntry structs
     */
    function getLeaderboard(
        uint256 _offset,
        uint256 _limit
    ) public view returns (LeaderboardEntry[] memory) {
        uint256 totalPlayers = allPlayers.length;

        if (_offset >= totalPlayers) {
            return new LeaderboardEntry[](0);
        }

        uint256 endIndex = _offset + _limit;
        if (endIndex > totalPlayers) {
            endIndex = totalPlayers;
        }

        uint256 resultLength = endIndex - _offset;
        LeaderboardEntry[] memory result = new LeaderboardEntry[](resultLength);

        // Create a temporary array to sort by best scores
        LeaderboardEntry[] memory allEntries = new LeaderboardEntry[](
            totalPlayers
        );
        for (uint256 i = 0; i < totalPlayers; i++) {
            address player = allPlayers[i];
            allEntries[i] = LeaderboardEntry({
                score: playerBestScore[player],
                playerName: playerNames[player],
                playerAddress: player
            });
        }

        // Sort by score (descending) - simple bubble sort for small arrays
        for (uint256 i = 0; i < totalPlayers - 1; i++) {
            for (uint256 j = 0; j < totalPlayers - i - 1; j++) {
                if (allEntries[j].score < allEntries[j + 1].score) {
                    LeaderboardEntry memory temp = allEntries[j];
                    allEntries[j] = allEntries[j + 1];
                    allEntries[j + 1] = temp;
                }
            }
        }

        // Copy the requested range
        for (uint256 i = 0; i < resultLength; i++) {
            result[i] = allEntries[_offset + i];
        }

        return result;
    }

    /**
     * @dev Gets the total number of players in the leaderboard
     * @return Total number of players
     */
    function getTotalScores() public view returns (uint256) {
        return allPlayers.length;
    }

    /**
     * @dev Administrative functions
     */
    function setGameOwner(address _newOwner) public onlyGameOwner {
        require(_newOwner != address(0), "Invalid address");
        address oldOwner = gameOwner;
        gameOwner = _newOwner;
        emit GameOwnerUpdated(oldOwner, _newOwner);
    }

    function setPaused(bool _paused) public onlyGameOwner {
        paused = _paused;
        emit ContractPaused(_paused);
    }

    /**
     * @dev Sets the security key for signing scores
     * @param _securityKey The new security key
     */
    function setSecurityKey(bytes32 _securityKey) public onlyGameOwner {
        securityKey = _securityKey;
        securityKeySet = true;
        emit SecurityKeyUpdated(_securityKey);
    }

    function getContractInfo()
        public
        view
        returns (
            address _gameOwner,
            bool _paused,
            uint256 _minTimeBetweenScores,
            bool _securityKeySet
        )
    {
        return (gameOwner, paused, MIN_TIME_BETWEEN_SCORES, securityKeySet);
    }
}

